import json

# Get products and ledger data
scope_title = "Plant 2103, Period 03"
children = scope_nodes(doc, scope_title)

products = {}
for node in children:
    if "Products" in node["title"]:
        for row in node["table"]["rows"]:
            code = row[0]
            products[code] = {"weight": float(row[4]), "opening_stock": int(row[5])}

daily_data = {} # {(day, product): {produced, ordered}}
for node in children:
    if "Daily ledger" in node["title"]:
        for row in node["table"]["rows"]:
            day = int(row[0])
            prod = row[2]
            daily_data[(day, prod)] = {
                "produced": int(row[3]),
                "ordered": int(row[4])
            }

# Simulation
capacity_limit = 407700.0
all_products = sorted(products.keys())
days = range(29, 43) # 29 to 42

# Initialize state at start of day 29
stock = {p: products[p]["opening_stock"] for p in all_products}
backorders = {p: [] for p in all_products} # list of {"day": d, "qty": q}
results = {}

for day in days:
    # 1. Production arrives
    for p in all_products:
        if (day, p) in daily_data:
            stock[p] += daily_data[(day, p)]["produced"]

    # 2. Orders join queue
    for p in all_products:
        if (day, p) in daily_data:
            ordered = daily_data[(day, p)]["ordered"]
            if ordered > 0:
                # Modify day 30 order for SOS002L09P
                if day == 30 and p == "SOS002L09P":
                    ordered = 0
                if ordered > 0:
                    backorders[p].append({"day": day, "qty": ordered})

    # 3. Dispatch
    # Flatten all open orders into a single list
    open_orders = []
    for p in all_products:
        for order in backorders[p]:
            if order["qty"] > 0:
                open_orders.append({"product": p, "day": order["day"], "qty": order["qty"], "ref": order})

    # Sort: oldest day first, then smaller remaining qty, then lower product code
    open_orders.sort(key=lambda x: (x["day"], x["qty"], x["product"]))

    capacity = capacity_limit
    shipped_today = {p: 0 for p in all_products}

    for order in open_orders:
        p = order["product"]
        if capacity <= 0:
            break

        weight = products[p]["weight"]
        max_by_stock = stock[p]
        max_by_cap = int(capacity / weight)
        to_ship = min(order["qty"], max_by_stock, max_by_cap)

        if to_ship > 0:
            stock[p] -= to_ship
            capacity -= to_ship * weight
            order["qty"] -= to_ship
            shipped_today[p] += to_ship

    # 4. Record results
    # Clean up empty backorders for this product
    total_backordered = {p: sum(o["qty"] for o in backorders[p]) for p in all_products}

    results[day] = {
        "stock": dict(stock),
        "backordered": total_backordered,
        "shipped": shipped_today
    }
    # Update backorders list to only keep those with qty > 0 (optional, but good for tracking)
    for p in all_products:
        backorders[p] = [o for o in backorders[p] if o["qty"] > 0]

