def simulate(capacity_override=None):
    """Simulate from day 57 to day 70"""
    # State
    stock = dict(opening_stock)
    # orders: list of (day_placed, product, remaining_quantity)
    orders = []

    results = {}

    for day in range(57, 71):
        if capacity_override and day >= 66:
            capacity = capacity_override
        else:
            capacity = 300000

        # Step 1: Production arrives
        if day in daily_data:
            for product, (produced, ordered) in daily_data[day].items():
                stock[product] += produced

        # Step 2: Orders join the queue
        if day in daily_data:
            for product, (produced, ordered) in daily_data[day].items():
                if ordered > 0:
                    orders.append((day, product, ordered))

        # Step 3: Dispatch
        remaining_capacity = capacity

        shipped_today = {product: 0 for product in stock}

        while remaining_capacity > 0 and orders:
            # Sort orders by (day_placed, remaining_quantity, product_code)
            sorted_orders = sorted(orders, key=lambda x: (x[0], x[2], x[1]))

            shipped_something = False
            for day_placed, product, remaining in sorted_orders:
                if remaining <= 0:
                    continue
                available_stock = stock[product]
                if available_stock <= 0:
                    continue

                # Determine how many units can be shipped
