def simulate_original():
    stock = dict(opening_stock)
    backordered = {p: 0 for p in products}
    orders = []
    results = {}

    for day in days:
        # Production arrives
        for p in products:
            prod = ledger_data[(day, p)]['produced']
            stock[p] += prod

        # Orders join queue
        for p in products:
            ord_qty = ledger_data[(day, p)]['ordered']
            if ord_qty > 0:
                orders.append((day, p, ord_qty))

        # Dispatch
        remaining_capacity = capacity
        shipped_today = {p: 0 for p in products}

        # Sort orders by priority
        current_orders = [(d, p, r) for (d, p, r) in orders]
        current_orders.sort(key=lambda x: (x[0], x[2], x[1]))

        new_orders = []
        for (day_placed, product, remaining) in current_orders:
            if remaining <= 0:
                continue

            max_by_stock = stock[product]
            max_by_capacity = remaining_capacity // weights[product] if weights[product] > 0 else 0
            units_to_ship = min(remaining, max_by_stock, max_by_capacity)

            if units_to_ship > 0:
                stock[product] -= units_to_ship
                remaining_capacity -= units_to_ship * weights[product]
                shipped_today[product] += units_to_ship
                remaining -= units_to_ship

            if remaining > 0:
                new_orders.append((day_placed, product, remaining))

        for p in products:
            backordered[p] = sum(r for (d, prod, r) in new_orders if prod == p)

        orders = new_orders

        for p in products:
            results[(day, p)] = {
                'stock': stock[p],
                'backordered': backordered[p],
                'shipped': shipped_today[p]
            }

    return results

