def simulate_day(day, open_orders, stock, backordered):
    daily_data = order_book[day]

    # Step 1: Production arrives
    for product, data in daily_data.items():
        produced = data['production']
        stock[product] += produced

    # Step 2: Orders join the queue
    for product, data in daily_data.items():
        ordered = data['ordered']
        if ordered > 0:
            open_orders.append({'product': product, 'day_placed': day, 'remaining': ordered})

    # Step 3: Dispatch
    open_orders.sort(key=lambda o: (o['day_placed'], o['remaining'], o['product']))

    capacity_remaining = dispatch_capacity
    shipped_today = {p: 0 for p in stock}

    orders_to_keep = []
